// expected_sig comes from "Verify Signature" (HMAC of shipment_id.exp with REVIEW_SIGNING_SECRET).
const { shipment_id, action, exp, sig } = $json.query ?? {};
const expected = $json.expected_sig ?? '';

let diff = typeof sig === 'string' && sig.length === expected.length ? 0 : 1;
for (let i = 0; !diff && i < expected.length; i++) diff |= expected.charCodeAt(i) ^ sig.charCodeAt(i);

let reason = null;
if (diff) reason = 'This review link is not valid.';
else if (Number(exp) < Date.now() / 1000) reason = 'This review link has expired. Open the order in the TMS instead.';
else if (!['approve', 'reject'].includes(action)) reason = `Unknown action "${action}".`;

return { json: { valid: !reason, reason, shipment_id, action } };

// Input is a dispatched TMS shipment. Shared by the intake and review workflows.
const s = $json;
const at = (t) => (t ? String(t).replace('T', ' ') : 'TBD');
const place = (stop = {}) => stop.formatted_address || [stop.street, stop.city, stop.state, stop.zip].filter(Boolean).join(', ');
const ref = s.reference_number ? ` (your ref ${s.reference_number})` : '';

const body = [
  `Hi ${s.customer?.contact_name ?? 'there'},`,
  '',
  `Your delivery is booked${ref}.`,
  '',
  `Shipment:      ${s.id}`,
  `Pickup:        ${place(s.pickup)}`,
  `Pickup ETA:    ${at(s.route?.pickup_eta)}`,
  `Deliver to:    ${place(s.dropoff)}`,
  `Delivery ETA:  ${at(s.route?.eta)}`,
  `Vehicle:       ${s.vehicle_type ?? 'Assigned by dispatch'}`,
  `Driver:        ${s.route?.driver?.name ?? 'Assigned shortly'}`,
  s.price != null ? `Price:         $${s.price.toFixed(2)}` : null,
  '',
  s.route?.tracking_url ? `Track it live: ${s.route.tracking_url}` : null,
  '',
  'Reply to this email if anything needs to change.',
  '',
  'Dispatch team',
].filter((line) => line !== null);

return {
  json: {
    shipment_id: s.id,
    email: {
      personalizations: [{ to: [{ email: s.customer?.email }] }],
      subject: `Booked: ${s.id}${ref}`,
      content: [{ type: 'text/plain', value: body.join('\n') }],
    },
  },
};

// Builds the page shown in the reviewer's browser. approved is set per node by build.py.
const outcome = 'approved';
const s = outcome === 'approved' ? $('TMS: Dispatch Approved').item.json
  : outcome === 'rejected' ? $('TMS: Cancel Shipment').item.json
  : $json;

const pages = {
  invalid: () => ({ http_status: 403, tone: 'bad', title: 'Link not valid', message: s.reason }),
  handled: () => ({
    http_status: 409,
    tone: 'info',
    title: `Already ${s.status}`,
    message: `Shipment ${s.id} is already ${s.status}, so nothing was changed.`,
  }),
  approved: () => ({
    http_status: 200,
    tone: 'good',
    title: `${s.id} approved`,
    message: `Booked and dispatched on route ${s.route?.id} with ${s.route?.driver?.name}. Pickup ETA ${String(s.route?.pickup_eta).replace('T', ' ')}. The customer has been emailed.`,
  }),
  rejected: () => ({
    http_status: 200,
    tone: 'bad',
    title: `${s.id} rejected`,
    message: 'The draft was cancelled in the TMS. Reply to the customer if you need more details from them.',
  }),
};

return { json: pages[outcome]() };

